-- Check if there's an issue with how we're computing PER - maybe the threshold comparison should use the computed value directly
-- Let me also check if "dust resistance length" and "water resistance length" refer to something else
SELECT dustres, waterres, LENGTH(dustres), LENGTH(waterres) FROM physicaldurability WHERE dustres = 'IPX3' LIMIT 5;

-- Check the relationship: mechanical.mechdevref -> deviceidentity.devregistry, and mechanical links to performance
-- Also check if there's a direct link from deviceidentity to physicaldurability via interactionandcontrol
SELECT COUNT(DISTINCT ic.interactdevref) FROM interactionandcontrol ic;

-- All interactdevref values exist in deviceidentity. Let me check if there's a 1:1 mapping
SELECT COUNT(*) FROM (
    SELECT di.devregistry, ic.interactphysref 
    FROM deviceidentity di
    JOIN interactionandcontrol ic ON di.devregistry = ic.interactdevref
) sub;
